#include <iostream>
using namespace std;

int main() {   //@ @layout open:visualizer
    int sum = 0;   //@ @tts [next] 先準備 sum，從 0 開始
    for (int i = 1; i <= 3; i++) {   //@ @tts [next] 進入迴圈 | @2 [next] 看看要不要再來一圈
        sum += i;   //@ @guide {i} @tts [next] 迴圈第 {i} 圈
    }
    cout << sum << endl;   //@ @tts [next] 全部跑完，總和是 {sum}
    return 0;   //@ @tts [continue] 程式結束
}
